# BundledCMDB data collector.
#
# Generated by lib/collect_script.php for the "Collect data" download. Keep this
# file ASCII-only: cmd.exe mangles a UTF-8 batch file and a redirected
# `Set-Content -Encoding ASCII` turns typographic characters into `?`.

$ErrorActionPreference = 'Continue'
$ProgressPreference = 'SilentlyContinue'

$endpoint = '__ENDPOINT__'
$token = '__TOKEN__'
$version = '__VERSION__'

function Write-Step([string]$text) {
    Write-Host ('  ' + $text)
}

function Get-DiskInventory {
    $disks = @()
    try {
        $physical = @(Get-Disk -ErrorAction Stop | Where-Object { $_.Size -gt 0 })
    } catch {
        return (Get-DiskInventoryCim)
    }
    foreach ($disk in $physical) {
        $volumes = @()
        $freeBytes = 0
        $totalBytes = 0
        try {
            foreach ($partition in @(Get-Partition -DiskNumber $disk.Number -ErrorAction SilentlyContinue)) {
                $volume = Get-Volume -Partition $partition -ErrorAction SilentlyContinue
                if ($null -eq $volume -or -not $volume.DriveLetter) { continue }
                $volumes += [ordered]@{
                    drive    = "$($volume.DriveLetter):"
                    label    = "$($volume.FileSystemLabel)"
                    total_gb = [math]::Round($volume.Size / 1GB, 2)
                    free_gb  = [math]::Round($volume.SizeRemaining / 1GB, 2)
                }
                $freeBytes += $volume.SizeRemaining
                $totalBytes += $volume.Size
            }
        } catch { }
        $media = ''
        try {
            $pd = Get-PhysicalDisk -DeviceNumber $disk.Number -ErrorAction SilentlyContinue
            if ($null -ne $pd) { $media = "$($pd.MediaType)" }
        } catch { }
        if ($media -eq '') { $media = "$($disk.BusType)" }
        $entry = [ordered]@{
            number        = [int]$disk.Number
            friendly_name = "$($disk.FriendlyName)"
            media_type    = $media
            bus_type      = "$($disk.BusType)"
            size_gb       = [math]::Round($disk.Size / 1GB, 2)
            volumes       = $volumes
        }
        if ($totalBytes -gt 0) { $entry.free_gb = [math]::Round($freeBytes / 1GB, 2) }
        $disks += $entry
    }
    return $disks
}

# Windows 7 / Server 2008 R2 have no Storage module: report the drives without
# per-volume free space instead of failing the whole collection.
function Get-DiskInventoryCim {
    $disks = @()
    $index = 0
    foreach ($drive in @(Get-CimInstance -ClassName Win32_DiskDrive -ErrorAction SilentlyContinue)) {
        if ($null -eq $drive.Size -or $drive.Size -le 0) { continue }
        $disks += [ordered]@{
            number        = $index
            friendly_name = "$($drive.Model)"
            media_type    = "$($drive.MediaType)"
            bus_type      = "$($drive.InterfaceType)"
            size_gb       = [math]::Round($drive.Size / 1GB, 2)
            volumes       = @()
        }
        $index = $index + 1
    }
    return $disks
}

function Get-LoggedUsers {
    $users = @()
    try {
        foreach ($process in @(Get-CimInstance Win32_Process -Filter "Name='explorer.exe'" -ErrorAction SilentlyContinue)) {
            $owner = Invoke-CimMethod -InputObject $process -MethodName GetOwner -ErrorAction SilentlyContinue
            if ($owner.User) { $users += "$($owner.Domain)\$($owner.User)" }
        }
    } catch { }
    return @($users | Select-Object -Unique)
}

function Get-IpAddresses {
    $addresses = @()
    try {
        $addresses = @(Get-NetIPAddress -AddressFamily IPv4 -ErrorAction Stop |
            Where-Object { $_.IPAddress -notlike '169.254.*' -and $_.IPAddress -ne '127.0.0.1' } |
            ForEach-Object { $_.IPAddress })
    } catch {
        try {
            foreach ($adapter in @(Get-CimInstance Win32_NetworkAdapterConfiguration -ErrorAction SilentlyContinue | Where-Object { $_.IPEnabled })) {
                foreach ($ip in @($adapter.IPAddress)) {
                    if ($ip -like '*.*' -and $ip -notlike '169.254.*' -and $ip -ne '127.0.0.1') { $addresses += $ip }
                }
            }
        } catch { }
    }
    return @($addresses | Select-Object -Unique)
}

function Get-MacAddresses {
    $macs = @()
    try {
        $macs = @(Get-CimInstance Win32_NetworkAdapterConfiguration -ErrorAction SilentlyContinue |
            Where-Object { $_.IPEnabled -and $_.MACAddress } |
            ForEach-Object { $_.MACAddress })
    } catch { }
    return @($macs | Select-Object -Unique)
}

function Get-AdapterNames {
    $names = @()
    try {
        $names = @(Get-CimInstance Win32_NetworkAdapter -ErrorAction SilentlyContinue |
            Where-Object { $_.NetEnabled -and $_.Name } |
            ForEach-Object { $_.Name })
    } catch { }
    return @($names | Select-Object -Unique)
}

function Get-CleanSerial([string]$serial) {
    $value = "$serial".Trim()
    $junk = @('', 'to be filled by o.e.m.', 'default string', 'none', 'not specified',
              'not applicable', 'system serial number', 'n/a', 'unknown', '0', '123456789')
    if ($junk -contains $value.ToLower()) { return '' }
    return $value
}

function Get-CleanUuid([string]$uuid) {
    $value = "$uuid".Trim()
    $junk = @('', '00000000-0000-0000-0000-000000000000',
              'ffffffff-ffff-ffff-ffff-ffffffffffff',
              '03000200-0400-0500-0006-000700080009')
    if ($junk -contains $value.ToLower()) { return '' }
    return $value
}

function Describe-Error([string]$code, [int]$status) {
    switch ($code) {
        'invalid_token'      { return 'The collector link is not valid. Download a new file from the panel.' }
        'token_revoked'      { return 'This file was replaced by a newer download. Use the most recent file.' }
        'token_expired'      { return 'The collector link expired. Download a new file from the panel and run it.' }
        'collect_disabled'   { return 'Data collection is switched off on this server.' }
        'user_not_found'     { return 'Your account is no longer on the authorised list. Contact your IT administrator.' }
        'company_unassigned' { return 'Your account has no company. Ask an administrator to assign one.' }
        'role_not_allowed'   { return 'Your role may not collect data. Ask your IT administrator.' }
        'device_assigned_to_other_user' { return 'This device is assigned to another person. Ask an administrator to change the owner.' }
        'serial_soft_deleted' { return 'This device was deleted from the inventory. Ask an administrator to restore it first.' }
        'serial_missing'     { return 'This machine did not report a serial number, which this server requires.' }
        'validation_failed'  { return 'The server rejected the collected data. Send this text to your IT administrator.' }
        'conflict'           { return 'A device with the same serial number or UUID already exists.' }
        'rate_limited'       { return 'Too many attempts. Wait a minute and run the file again.' }
    }
    if ($status -eq 401) { return 'The server did not accept this file. Download a new one from the panel.' }
    if ($status -eq 403) { return 'The server refused the request. Contact your IT administrator.' }
    return "The server answered with an unexpected error (HTTP $status)."
}

Write-Host ''
Write-Host ' BundledCMDB - collect device data'
Write-Host ' ---------------------------------'
Write-Host " Server: $endpoint"
Write-Host ''

Write-Step 'Reading system information...'

$cs = Get-CimInstance -ClassName Win32_ComputerSystem -ErrorAction SilentlyContinue
$os = Get-CimInstance -ClassName Win32_OperatingSystem -ErrorAction SilentlyContinue
$bios = Get-CimInstance -ClassName Win32_BIOS -ErrorAction SilentlyContinue
$product = Get-CimInstance -ClassName Win32_ComputerSystemProduct -ErrorAction SilentlyContinue
$processor = Get-CimInstance -ClassName Win32_Processor -ErrorAction SilentlyContinue

$hostname = "$($cs.Name)"
$serial = Get-CleanSerial "$($bios.SerialNumber)"
$uuid = Get-CleanUuid "$($product.UUID)"
$cpuNames = @($processor | ForEach-Object { "$($_.Name)".Trim() } | Where-Object { $_ -ne '' })
$cpu = $cpuNames -join ', '
$gpuNames = @()
try {
    $gpuNames = @(Get-CimInstance -ClassName Win32_VideoController -ErrorAction SilentlyContinue |
        ForEach-Object { "$($_.Name)".Trim() } | Where-Object { $_ -ne '' })
} catch { }
$gpu = $gpuNames -join ', '
$ramGb = 0
if ($cs.TotalPhysicalMemory) { $ramGb = [math]::Round($cs.TotalPhysicalMemory / 1GB) }

$ips = @(Get-IpAddresses)
$primaryIp = ''
if ($ips.Count -gt 0) { $primaryIp = "$($ips[0])" }
$macs = @(Get-MacAddresses)
$adapters = @(Get-AdapterNames)

$secureBoot = $null
try {
    $bootState = Get-ItemProperty -Path 'HKLM:\SYSTEM\CurrentControlSet\Control\SecureBoot\State' -Name 'UEFISecureBootEnabled' -ErrorAction Stop
    if ($null -ne $bootState.UEFISecureBootEnabled) {
        if ([int]$bootState.UEFISecureBootEnabled -eq 1) { $secureBoot = 'true' } else { $secureBoot = 'false' }
    }
} catch { }

$antivirus = ''
try {
    $av = @(Get-CimInstance -Namespace 'root/SecurityCenter2' -ClassName AntiVirusProduct -ErrorAction Stop |
        ForEach-Object { "$($_.displayName)".Trim() } | Where-Object { $_ -ne '' })
    $antivirus = $av -join ', '
} catch { }

$loggedUsers = @(Get-LoggedUsers)
$consoleUser = "$($cs.UserName)"
$loggedUser = ''
if ($consoleUser -ne '') {
    $loggedUser = $consoleUser
} elseif ($loggedUsers.Count -gt 0) {
    $loggedUser = "$($loggedUsers[0])"
} else {
    $loggedUser = "$env:USERDOMAIN\$env:USERNAME"
}

$disks = @(Get-DiskInventory)

Write-Step 'Sending the data to the server...'

$payload = [ordered]@{
    uuid                   = $uuid
    sn                     = $serial
    hostname               = $hostname
    os                     = "$($os.Caption)"
    os_version             = "$($os.Version)"
    manufacturer           = "$($cs.Manufacturer)"
    cpus                   = $cpu
    primary_local_ip       = $primaryIp
    physical_disks         = $disks
    network_adapters       = ($adapters -join ', ')
    mac_addresses          = ($macs -join ', ')
    agent_hostname         = $hostname
    agent_os               = "$($os.Caption)"
    agent_os_build         = "$($os.BuildNumber)"
    agent_bios             = "$($bios.SMBIOSBIOSVersion)"
    agent_secure_boot      = $secureBoot
    agent_manufacturer     = "$($cs.Manufacturer)"
    agent_model            = "$($cs.Model)"
    agent_cpu              = $cpu
    agent_gpu              = $gpu
    agent_ram_gb           = "$ramGb"
    agent_ip               = $primaryIp
    agent_logged_user      = $loggedUser
    agent_all_logged_users = ($loggedUsers -join ', ')
    agent_execution_user   = "$env:USERDOMAIN\$env:USERNAME"
    agent_antivirus        = $antivirus
}

$json = $payload | ConvertTo-Json -Depth 6 -Compress
$body = [System.Text.Encoding]::UTF8.GetBytes($json)
$headers = @{ 'X-Collector-Token' = $token; 'X-Collector-Version' = $version }

$status = 0
$code = ''
$deviceName = ''
$created = $false
try {
    $response = Invoke-RestMethod -Uri $endpoint -Method Post -Headers $headers -Body $body -ContentType 'application/json; charset=utf-8' -TimeoutSec 60
    $status = 200
    if ($null -ne $response -and $null -ne $response.data -and $null -ne $response.data.device) {
        $deviceName = "$($response.data.device.hostname)"
        $created = [bool]$response.data.created
    }
} catch {
    $webResponse = $null
    try { $webResponse = $_.Exception.Response } catch { }
    if ($null -ne $webResponse) {
        try { $status = [int]$webResponse.StatusCode } catch { }
        try {
            $reader = New-Object System.IO.StreamReader($webResponse.GetResponseStream())
            $raw = $reader.ReadToEnd()
            $reader.Dispose()
            $parsed = $raw | ConvertFrom-Json
            if ($null -ne $parsed -and $null -ne $parsed.error) { $code = "$($parsed.error.code)" }
        } catch { }
    }
}

Write-Host ''
if ($status -eq 200) {
    $name = $deviceName
    if ($name -eq '') { $name = $hostname }
    if ($created) {
        Write-Host " Done. The device '$name' was added to the inventory."
    } else {
        Write-Host " Done. The device '$name' was updated in the inventory."
    }
    Write-Host ' You can close this window.'
} else {
    if ($status -eq 0) {
        Write-Host ' The server could not be reached.'
        Write-Host ' Check the internet connection (or the VPN) and run the file again.'
    } else {
        Write-Host ' The data was not sent.'
        Write-Host (' ' + (Describe-Error $code $status))
    }
    Write-Host ''
    Write-Host " Details: HTTP $status $code"
}

if ($status -eq 200) { exit 0 }
exit 1
